/* =====================================================================
   Views 3: Patients, Parties (customers/suppliers), Reports, Alerts, Settings
   ===================================================================== */

/* ---------------- Patients ---------------- */
const PU={q:'',f:'all'};
const rxLabel=r=>(r.nm||'')+(r.pot?' '+r.pot:'');
const nextPatNo=()=>String(Math.max(0,...DB.all('patients').map(p=>parseInt(p.no)||0))+1);
V.patients={title:'Patients',render(){
  const all=DB.all('patients');
  return`<div class="bar"><div class="search">${ico('search')}<input data-i="pat-q" placeholder="Search name, phone, case no…" value="${esc(PU.q)}" dir="auto"></div><button class="btn pri" data-a="pat-new">${ico('plus')} New patient</button></div>
  <div class="chips">${[['all','All · '+all.length],['fu','Follow-up due'],['run','On medicine now'],['new','New this month']].map(([k,t])=>`<button class="chip ${PU.f===k?'on':''}" data-a="pat-f" data-f="${k}">${t}</button>`).join('')}${all.length?`<button class="chip" data-a="pat-export">${ico('file')} Export list</button>`:''}</div><div id="plist"></div>`},mount(){drawPats()}};
A['pat-f']=d=>{PU.f=d.f;render(true)};
function drawPats(){const el=$('#plist');if(!el)return;const q=PU.q.toLowerCase(),t=ymd(),mo=t.slice(0,7);
  const ps=DB.all('patients').filter(p=>{if(q&&!(p.name+' '+(p.phone||'')+' '+(p.no||'')+' '+(p.addr||'')).toLowerCase().includes(q))return false;
    if(PU.f==='fu')return patStats(p.id).fu&&patStats(p.id).fu.follow<=addDays(2);if(PU.f==='run')return patCourses(p.id).some(c=>c.st==='running');if(PU.f==='new')return ymd(new Date(p._u)).startsWith(mo)&&(p.c||p._u)>=Date.now()-31*864e5;return true}).sort((a,b)=>a.name.localeCompare(b.name));
  el.innerHTML=ps.length?ps.map(p=>{const st=patStats(p.id),run=patCourses(p.id).filter(c=>c.st==='running').length;
    return`<div class="row" data-a="pat-open" data-id="${p.id}"><span class="av">${esc((p.name||'?')[0].toUpperCase())}</span><div class="r-main"><b>${esc(p.name)}</b><small>${[p.no&&'#'+p.no,patAge(p)&&patAge(p)+'y',p.sex,p.phone].filter(Boolean).map(esc).join(' · ')}</small><small>${st.n?`${st.n} visit${st.n>1?'s':''} · last ${fdate(st.last.d)} (${todOf(st.last.t||0)})`:'No visits yet'}</small></div><div class="r-side">${st.fu?`<span class="badge ${st.fu.follow<=ymd()?'bad':'warn'}">Follow-up ${fdate(st.fu.follow)}</span>`:''}${run?`<span class="badge ok">${run} medicine${run>1?'s':''} running</span>`:''}</div></div>`}).join(''):emptyBox(DB.all('patients').length?'No patients match':'No patients yet','Keep case history, prescriptions, medicine courses and follow-ups here.',`<button class="btn pri" data-a="pat-new">${ico('plus')} New patient</button>`)}
HI['pat-q']=v=>{PU.q=v;drawPats()};
A['pat-new']=()=>patForm();
A['pat-export']=()=>{const rows=DB.all('patients').sort((a,b)=>a.name.localeCompare(b.name)).map(p=>{const st=patStats(p.id);return[p.no||'',p.name,patAge(p),p.sex||'',p.phone||'',p.addr||'',st.n,st.last?st.last.d:'',st.fu?st.fu.follow:'',patCourses(p.id).filter(c=>c.st==='running').map(c=>rxLabel(c)).join(', ')]});
  exportMenu({title:'Patients list',head:['Case no','Name','Age','Sex','Phone','Address','Visits','Last visit','Next follow-up','Medicines running'],rows,text:null})};
const sel=(l,n,list,cur)=>F.s(l,n,['',...list],cur||'');
function patForm(id,cb){
  const p=id?DB.get('patients',id):{};
  modal({title:id?'Edit patient':'New patient',cls:'wide',sticky:true,html:`<form class="stack" onsubmit="return false">
   ${fsec('1 · Who is the patient',`${F.t('Full name *','name',p.name,{required:true,autofocus:true})}
    <div class="grid g3">${F.t('Case / registration no.','no',p.no||nextPatNo())}${F.t('Age (years)','age',p.age,{inputmode:'numeric'})}${F.d('or Date of birth','dob',p.dob||'')}</div>
    <div class="grid g3">${F.s('Sex','sex',['','Male','Female','Other'],p.sex||'')}${F.s('Marital status','marital',['','Single','Married','Widowed','Divorced'],p.marital||'')}${F.s('Blood group','blood',BLOODS,p.blood||'')}</div>
    <div class="grid g2">${F.t('Phone / WhatsApp','phone',p.phone,{inputmode:'tel'})}${F.t('Other phone','phone2',p.phone2,{inputmode:'tel'})}</div>
    <div class="grid g2">${F.t('Occupation','job',p.job)}${F.t('Referred by / how they came','ref',p.ref)}</div>${F.t('Address','addr',p.addr)}`)}
   ${fsec('2 · Health background',`${F.a('Allergies (medicine, food, dust…)','allergy',p.allergy,{rows:2})}${F.a('Past illnesses, surgeries &amp; long-term diseases (BP, sugar, thyroid…)','history',p.history,{rows:3})}${F.a('Family history','family',p.family,{rows:2})}${F.a('Other medicines they are taking now (allopathic / other)','othermeds',p.othermeds,{rows:2})}${F.a('Habits (smoking, tea, pan, exercise…)','habits',p.habits,{rows:2})}`)}
   ${fsec('3 · General symptoms &amp; constitution (optional)',`<div class="grid g3">${sel('Reaction to weather','thermal',['Hot patient','Chilly patient','Ambithermal'],p.thermal)}${sel('Thirst','thirst',['Thirstless','Little thirst','Normal','Thirsty','Very thirsty'],p.thirst)}${sel('Appetite','appetite',['Poor','Normal','Good','Ravenous'],p.appetite)}</div><div class="grid g3">${sel('Sleep','sleep',['Sound','Disturbed','Sleepless','Excess sleep'],p.sleep)}${sel('Perspiration','sweat',['Scanty','Normal','Profuse'],p.sweat)}${F.t('Desires / aversions (food)','desires',p.desires)}</div>${F.a('Mind, temperament, fears, stress…','mind',p.mind,{rows:2})}`)}
   ${fsec('4 · Notes',F.a('Anything else to remember','note',p.note,{rows:3}))}</form>`,
   foot:[{t:'Cancel',fn:()=>{}},{t:'Save patient',cls:'pri',fn:el=>{const f=formData(el);if(!f.name.trim()){toast('Name is required','bad');return false}
     const r=DB.put('patients',{...p,...f,name:f.name.trim(),c:p.c||Date.now()});toast('Patient saved','ok');cb?cb(r.id):0}}]})}
A['pat-open']=d=>openPatient(d.id);
let PTAB='over';
const kvRow=(k,v)=>v?`<dt>${k}</dt><dd>${esc(v)}</dd>`:'';
const stChip=c=>c.st==='running'?`<span class="badge ok">Running · ${c.left===0?'ends today':c.left+' day'+(c.left>1?'s':'')+' left'}</span>`:c.st==='finished'?`<span class="badge mut">Finished ${fdate(c.last.end)}</span>`:c.st==='stopped'?`<span class="badge bad">Stopped</span>`:`<span class="badge">No duration set</span>`;
function openPatient(id,tab){
  const p=DB.get('patients',id);if(!p)return;if(tab)PTAB=tab;
  const st=patStats(id);
  const m=modal({title:esc(p.name),cls:'full',sticky:false,html:`<div class="stack" data-pid="${id}">
   <div class="pstats"><div><small>Visits</small><b>${st.n}</b></div><div><small>First visit</small><b>${st.first?fdate(st.first):'—'}</b></div><div><small>Last visit</small><b>${st.last?fdate(st.last.d):'—'}</b></div><div><small>Usual gap</small><b>${st.avgGap?st.avgGap+' days':'—'}</b></div><div><small>Next follow-up</small><b style="${st.fu&&st.fu.follow<=ymd()?'color:var(--bad)':''}">${st.fu?fdate(st.fu.follow):'—'}</b></div></div>
   <div class="grid g3"><button class="btn pri" data-a="visit-new" data-id="${id}">${ico('plus')} New visit</button><button class="btn" data-a="pat-repeat" data-id="${id}">${ico('copy')} Repeat last Rx</button><button class="btn" data-a="pat-edit" data-id="${id}">${ico('edit')} Edit details</button></div>
   ${st.fu&&p.phone?`<button class="btn block" data-a="fu-wa" data-id="${st.fu.id}">${ico('chat')} WhatsApp follow-up reminder (${fdate(st.fu.follow)})</button>`:''}
   <div class="tabs" id="ptabs">${[['over','Overview'],['visits','Visits ('+st.n+')'],['meds','Medicines'],['bills','Bills']].map(([k,t])=>`<button class="${PTAB===k?'on':''}" data-a="pat-tab" data-t="${k}">${t}</button>`).join('')}</div><div id="pbody"></div></div>`,mount(el){drawPBody(id)}});return m}
A['pat-tab']=(d,b)=>{PTAB=d.t;const root=b.closest('[data-pid]');$$('#ptabs button',root).forEach(x=>x.classList.toggle('on',x.dataset.t===d.t));drawPBody(root.dataset.pid)};
function drawPBody(id){const el=$('#pbody');if(!el)return;const p=DB.get('patients',id);if(!p)return;
  const vs=patVisits(id).slice().reverse(),cs=patCourses(id);
  if(PTAB==='over'){const run=cs.filter(c=>c.st==='running'),lv=vs[0];
    el.innerHTML=`<div class="card"><h2>Details</h2><dl class="kv">${kvRow('Case no.',p.no)}${kvRow('Age / sex',[patAge(p)&&patAge(p)+' years',p.sex].filter(Boolean).join(' · '))}${kvRow('Date of birth',p.dob&&fdate(p.dob))}${kvRow('Marital status',p.marital)}${kvRow('Blood group',p.blood)}${kvRow('Phone',p.phone)}${kvRow('Other phone',p.phone2)}${kvRow('Address',p.addr)}${kvRow('Occupation',p.job)}${kvRow('Referred by',p.ref)}</dl></div>
    ${lv?`<div class="card"><h2><span>Last visit</span><span class="badge">${fdate(lv.d)} · ${todOf(lv.t||0)}</span></h2>${lv.complaint?`<div><b>Complaint:</b> <span dir="auto">${esc(lv.complaint)}</span></div>`:''}${lv.outcome?`<div style="margin-top:.3rem"><b>Result:</b> ${esc(lv.outcome)}</div>`:''}</div>`:''}
    <div class="card"><h2><span>Medicines running now</span><span class="badge ok">${run.length}</span></h2>${run.length?run.map(c=>`<div class="row static"><div class="r-main"><b>${esc(rxLabel(c))}</b><small>${esc([c.last.dose,c.last.freq].filter(Boolean).join(' · '))}</small></div>${stChip(c)}</div>`).join(''):'<div class="mut">No medicine is running. Add a prescription with days to track it.</div>'}</div>
    ${(p.allergy||p.history||p.family||p.othermeds||p.habits)?`<div class="card"><h2>Health background</h2><dl class="kv">${kvRow('Allergies',p.allergy)}${kvRow('Past / long-term illness',p.history)}${kvRow('Family history',p.family)}${kvRow('Other medicines',p.othermeds)}${kvRow('Habits',p.habits)}</dl></div>`:''}
    ${(p.thermal||p.thirst||p.appetite||p.sleep||p.sweat||p.desires||p.mind)?`<div class="card"><h2>Constitution</h2><dl class="kv">${kvRow('Weather',p.thermal)}${kvRow('Thirst',p.thirst)}${kvRow('Appetite',p.appetite)}${kvRow('Sleep',p.sleep)}${kvRow('Perspiration',p.sweat)}${kvRow('Desires / aversions',p.desires)}${kvRow('Mind',p.mind)}</dl></div>`:''}
    ${noteBox(p.note)}<div class="grid g2"><button class="btn" data-a="note-new" data-ref="${esc('Patient: '+p.name)}">${ico('note')} Add note</button>${p.phone?`<button class="btn" data-a="pat-wa" data-id="${id}">${ico('chat')} WhatsApp</button>`:''}</div><button class="btn bad block" data-a="pat-del" data-id="${id}">${ico('trash')} Delete patient</button>`;return}
  if(PTAB==='visits'){el.innerHTML=vs.length?vs.map(v=>{const ch=rxChange(v);
    return`<div class="card visit"><h2><span>${fdate(v.d)} <small class="mut" style="font-weight:600">· ${todOf(v.t||0)} ${v.t?ftime(v.t):''}</small></span><span style="display:flex;gap:.3rem;flex-wrap:wrap;justify-content:flex-end">${v.vtype?`<span class="badge">${esc(v.vtype)}</span>`:''}${v.outcome?`<span class="badge ${/better/i.test(v.outcome)?'ok':v.outcome==='Worse'?'bad':'warn'}">${esc(v.outcome)}</span>`:''}${v.follow?`<span class="badge ${v.fdone?'ok':v.follow<=ymd()?'bad':'warn'}">${v.fdone?'Follow-up done':'Follow-up '+fdate(v.follow)}</span>`:''}${num(v.fee)?`<span class="badge">Fee ${money(num(v.fee))}</span>`:''}</span></h2>
     <dl class="kv left">${kvRow('Complaint',v.complaint)}${kvRow('Since',v.since)}${kvRow('Symptoms',v.symptoms)}${kvRow('Progress',v.progress)}${kvRow('Examination',v.exam)}${kvRow('Vitals',[v.bp&&'BP '+v.bp,v.pulse&&'Pulse '+v.pulse,v.temp&&'Temp '+v.temp,v.wt&&'Wt '+v.wt,v.spo2&&'SpO₂ '+v.spo2].filter(Boolean).join(' · '))}${kvRow('Diagnosis',v.dx)}</dl>
     ${(v.rx||[]).filter(r=>r.nm).length?`<div style="margin-top:.5rem"><b>Prescription</b>${v.rx.filter(r=>r.nm).map(r=>`<div class="row static" style="margin:.25rem 0"><div class="r-main"><b>${esc(rxLabel(r))}</b><small>${esc([r.medium,r.dir||[r.dose,r.freq].filter(Boolean).join(' '),r.days&&r.days+' days',r.qty&&'qty '+r.qty].filter(Boolean).join(' · '))}${num(r.days)?' · till '+fdate(addD(v.d,num(r.days))):''}</small></div>${r.stop?`<span class="badge bad">Stopped ${fdate(r.stop)}</span>`:''}</div>`).join('')}</div>`:''}
     ${ch?`<div class="inline-note" style="margin-top:.5rem"><b>Medicine changed:</b> ${ch.added.length?'added '+esc(ch.added.join(', ')):''}${ch.added.length&&ch.dropped.length?' · ':''}${ch.dropped.length?'stopped '+esc(ch.dropped.join(', ')):''}${v.chgReason?'<br>Reason: '+esc(v.chgReason):''}</div>`:''}
     ${(v.parhez||[]).length?`<div style="margin-top:.4rem"><b>Parhez:</b> ${esc(v.parhez.join(' · '))}</div>`:''}${v.advice?`<div style="margin-top:.4rem"><b>Advice:</b> <span dir="auto">${esc(v.advice)}</span></div>`:''}${v.notes?`<div style="margin-top:.4rem">${noteBox(v.notes)}</div>`:''}
     <div class="bar" style="margin:.7rem 0 0"><button class="btn sm" data-a="visit-edit" data-id="${v.id}">${ico('edit')} Edit</button><button class="btn sm" data-a="visit-print" data-id="${v.id}">${ico('print')} Print Rx</button><button class="btn sm" data-a="visit-repeat" data-id="${v.id}">${ico('copy')} Repeat</button><button class="btn sm" data-a="visit-wa" data-id="${v.id}">${ico('chat')} Send</button><button class="btn sm pri" data-a="visit-bill" data-id="${v.id}">${ico('cart')} Bill this Rx</button>${v.follow&&!v.fdone?`<button class="btn sm" data-a="visit-done" data-id="${v.id}">${ico('check')} Follow-up done</button>`:''}<button class="btn sm bad" data-a="visit-del" data-id="${v.id}">${ico('trash')}</button></div></div>`}).join(''):emptyBox('No visits yet','Record the first visit to start the history.',`<button class="btn pri" data-a="visit-new" data-id="${id}">${ico('plus')} New visit</button>`);return}
  if(PTAB==='meds'){el.innerHTML=cs.length?cs.map(c=>`<div class="card"><h2><span>${esc(rxLabel(c))}</span>${stChip(c)}</h2>
     <div class="pstats sm"><div><small>Prescribed</small><b>${c.times}×</b></div><div><small>First</small><b>${fdate(c.first)}</b></div><div><small>Last</small><b>${fdate(c.last.d)}</b></div><div><small>Bought here</small><b>${c.it?c.rebuys+'×':'—'}</b></div></div>
     <div class="tw" style="margin-top:.6rem"><table class="t"><thead><tr><th>Given on</th><th>Dose</th><th>How often</th><th class="n">Days</th><th>Until</th></tr></thead><tbody>${c.list.slice().reverse().map(x=>`<tr><td>${fdate(x.d)}</td><td>${esc(x.dose||'—')}</td><td>${esc(x.freq||'—')}</td><td class="n">${x.days||'—'}</td><td>${x.stop?'<span style="color:var(--bad)">stopped '+fdate(x.stop)+(x.reason?' – '+esc(x.reason):'')+'</span>':x.end?fdate(x.end):'—'}</td></tr>`).join('')}</tbody></table></div>
     <div class="bar" style="margin:.6rem 0 0">${c.st!=='stopped'?`<button class="btn sm" data-a="course-stop" data-pid="${id}" data-k="${esc(c.key)}">Stop this medicine</button>`:''}<button class="btn sm" data-a="course-repeat" data-pid="${id}" data-k="${esc(c.key)}">${ico('copy')} Prescribe again</button></div></div>`).join(''):emptyBox('No medicines yet','Medicines you prescribe in a visit appear here with their dates, days left and how many times the patient bought them.');return}
  const bills=DB.all('sales').filter(s=>s.pat===id&&!s.void).sort((a,b)=>b.t-a.t);
  el.innerHTML=bills.length?bills.map(s=>`<div class="row" data-a="sale-open" data-id="${s.id}"><div class="r-main"><b>${esc(s.no)} · ${fdate(s.d)}</b><small>${esc(s.lines.map(l=>l.nm).join(', ').slice(0,80))}</small></div><div class="r-side"><b>${money(s.total)}</b></div></div>`).join('')+`<div class="mut" style="text-align:right">Total spent: <b>${money(bills.reduce((a,s)=>a+s.total,0))}</b></div>`:emptyBox('No bills linked','Choose this patient in “Discount, payment, patient” while billing, or use “Bill this Rx”.')}
A['pat-edit']=d=>{A.closeTop();patForm(d.id,id=>openPatient(id))};
A['pat-wa']=d=>{const p=DB.get('patients',d.id);window.open(waUrl(p.phone,`Assalam o Alaikum ${p.name},\n— ${CFG().shop}`),'_blank')};
A['pat-del']=async d=>{const p=DB.get('patients',d.id);if(!await ask(`Delete patient "${p.name}" and all their visits?`,{ok:'Delete',bad:true}))return;DB.all('visits').filter(v=>v.pat===d.id).forEach(v=>DB.del('visits',v.id));DB.del('patients',d.id);A.closeTop()};
A['pat-print']=d=>{const p=DB.get('patients',d.id),vs=patVisits(d.id),cs=patCourses(d.id),st=patStats(d.id);
  printDoc(docHead('Patient history',`${p.name}${patAge(p)?' · '+patAge(p)+'y':''}${p.sex?' · '+p.sex:''}${p.no?' · Case #'+p.no:''}${p.phone?' · '+p.phone:''}`,true)
   +`<table class="kvt"><tbody>${[['Address',p.addr],['Allergies',p.allergy],['Past / long-term illness',p.history],['Family history',p.family],['Habits',p.habits],['Constitution',[p.thermal,p.thirst&&'Thirst: '+p.thirst,p.appetite&&'Appetite: '+p.appetite,p.sleep&&'Sleep: '+p.sleep].filter(Boolean).join(', ')],['Visits',st.n+(st.first?' (first '+fdate(st.first)+', last '+fdate(st.last.d)+')':'')]].filter(r=>r[1]).map(r=>`<tr><td>${esc(r[0])}</td><td>${esc(r[1])}</td></tr>`).join('')}</tbody></table>`
   +(cs.length?`<h2>Medicines</h2>`+tableHTML(['Medicine','Times prescribed','Last given','Status'],cs.map(c=>[rxLabel(c),c.times,fdate(c.last.d),c.st==='running'?'Running ('+c.left+' days left)':c.st==='finished'?'Finished '+fdate(c.last.end):c.st==='stopped'?'Stopped':'—'])):'')
   +(vs.length?`<h2>Visits</h2>`+tableHTML(['Date','Time','Complaint','Prescription','Result'],vs.map(v=>[fdate(v.d),todOf(v.t||0),v.complaint||'',(v.rx||[]).filter(r=>r.nm).map(r=>rxLabel(r)+(r.dose?' ('+r.dose+(r.days?', '+r.days+'d':'')+')':'')).join('; '),v.outcome||''])):''))};
A['visit-new']=d=>{if(modals.length&&d.cl!==undefined)A.closeTop();visitForm(d.id)};
A['visit-edit']=d=>visitForm(DB.get('visits',d.id).pat,d.id);
A['visit-done']=d=>{const v=DB.get('visits',d.id);DB.put('visits',{...v,fdone:1});PTAB='visits';A.closeTop();openPatient(v.pat)};
A['visit-del']=async d=>{const v=DB.get('visits',d.id);if(!await ask('Delete this visit?',{ok:'Delete',bad:true}))return;DB.del('visits',d.id);A.closeTop();openPatient(v.pat)};
A['visit-repeat']=d=>{const v=DB.get('visits',d.id);visitForm(v.pat,null,{rx:(v.rx||[]).filter(r=>r.nm&&!r.stop).map(r=>({...r,stop:'',reason:''})),vtype:'Follow-up'})};
A['course-repeat']=d=>{const c=patCourses(d.pid).find(x=>x.key===d.k);if(!c)return;const l=c.last;visitForm(d.pid,null,{vtype:'Repeat medicine only',rx:[{it:c.it,nm:c.nm,pot:c.pot,dose:l.dose,freq:l.freq,days:l.days||'',qty:l.qty||''}]})};
A['course-stop']=d=>{const c=patCourses(d.pid).find(x=>x.key===d.k);if(!c)return;
  modal({title:'Stop '+esc(rxLabel(c)),html:`<form class="stack" onsubmit="return false"><p class="mut" style="margin:0">Mark that the patient should no longer take this medicine.</p>${F.d('Stopped on','d',ymd())}${F.t('Reason (better, no effect, side effect, changed…)','reason','')}</form>`,
   foot:[{t:'Cancel',fn:()=>{}},{t:'Stop medicine',cls:'bad',fn:el=>{const f=formData(el),v=DB.get('visits',c.last.vid);if(!v)return;DB.put('visits',{...v,rx:v.rx.map(r=>rxKey(r)===c.key&&!r.stop?{...r,stop:f.d||ymd(),reason:f.reason}:r)});toast('Marked as stopped','ok');drawPBody(d.pid)}}]})};
A['visit-bill']=d=>{const v=DB.get('visits',d.id);A.closeModals&&A.closeModals();while(modals.length)modals[modals.length-1].close();
  (v.rx||[]).forEach(r=>{if(r.it){posAdd(r.it);const L=CART.lines.find(l=>l.it===r.it&&!l.mx);if(L&&num(r.qty)>0)L.q=num(r.qty)}});CART.pat=v.pat;
  if(num(v.fee)>0&&!CART.lines.some(l=>l.nm==='Consultation fee'))CART.lines.push({it:'',nm:'Consultation fee',q:1,p:num(v.fee)});saveCart();location.hash='#/sell';toast('Prescription loaded into the bill','ok')};
A['visit-wa']=d=>{const v=DB.get('visits',d.id),p=DB.get('patients',v.pat);window.open(waUrl(p.phone,rxText(v,p)),'_blank')};
A['fu-wa']=d=>{const v=DB.get('visits',d.id),p=DB.get('patients',v.pat);if(!p)return;if(!p.phone)toast('This patient has no phone number','bad');window.open(waUrl(p.phone,followMsg(p,v)),'_blank')};
A['pat-repeat']=d=>{const vs=patVisits(d.id).filter(v=>(v.rx||[]).some(r=>r.nm));const l=vs[vs.length-1];if(!l){toast('No earlier prescription to repeat','bad');return}A['visit-repeat']({id:l.id})};
A['visit-print']=d=>{const v=DB.get('visits',d.id),p=DB.get('patients',v.pat),c=CFG();
  const vit=[v.bp&&'BP '+v.bp,v.pulse&&'Pulse '+v.pulse,v.temp&&'Temp '+v.temp,v.wt&&'Weight '+v.wt,v.spo2&&'SpO₂ '+v.spo2].filter(Boolean).join('  ·  ');
  printDoc(docHead('Prescription',`${p.name}${patAge(p)?' · '+patAge(p)+'y':''}${p.sex?' · '+p.sex:''}${p.no?' · Case #'+p.no:''}${p.phone?' · '+p.phone:''}`,true)+`<p>Date: <b>${fdate(v.d)}</b>${v.t?' · '+ftime(v.t):''}${v.vtype?' · '+esc(v.vtype):''}</p>`
   +(v.complaint?`<p><b>Complaint:</b> ${esc(v.complaint)}${v.since?' (since '+esc(v.since)+')':''}</p>`:'')+(vit?`<p><b>Vitals:</b> ${esc(vit)}</p>`:'')+(v.dx?`<p><b>Diagnosis:</b> ${esc(v.dx)}</p>`:'')
   +tableHTML(['Medicine','Medium','Directions','Days'],(v.rx||[]).filter(r=>r.nm).map(r=>[rxLabel(r),r.medium||'',r.dir||[r.dose,r.freq].filter(Boolean).join(', '),r.days?String(r.days):'']))
   +((v.parhez||[]).length?`<p><b>Parhez (diet rules):</b></p><ul style="margin:.2rem 0 .6rem 1.1rem;padding:0">${v.parhez.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'')
   +(v.advice?`<p><b>Advice / diet:</b> ${esc(v.advice)}</p>`:'')+(v.follow?`<p><b>Next visit / follow-up:</b> ${fdate(v.follow)}</p>`:'')+`<div class="sig"><span>${esc(c.doc||'Doctor')}</span></div>`)};
/* ----- visit form ----- */
let VE=null;
const vtime=v=>{const d=new Date(v.t||Date.now());return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};
function visitForm(patId,id,seed){
  const base={pat:patId,d:ymd(),vtype:patVisits(patId).length?'Follow-up':'New case',complaint:'',since:'',symptoms:'',progress:'',exam:'',bp:'',pulse:'',temp:'',wt:'',spo2:'',dx:'',rx:[],advice:'',parhez:[],chgReason:'',outcome:'',notes:'',follow:'',fee:''};
  const v=id?DB.get('visits',id):{...base,...(seed||{})};VE=JSON.parse(JSON.stringify(v));VE.tm=vtime(v);
  const p=DB.get('patients',patId)||{};
  const fld=(l,f,o={})=>`<label class="fld">${l}${o.area?`<textarea data-i="ve" data-f="${f}" dir="auto" rows="${o.area}" placeholder="${esc(o.ph||'')}">${esc(VE[f])}</textarea>`:`<input data-i="ve" data-f="${f}" value="${esc(VE[f])}" dir="auto" ${o.num?'inputmode="decimal"':''} placeholder="${esc(o.ph||'')}">`}</label>`;
  modal({title:(id?'Edit visit':'New visit')+' · '+esc(p.name||''),cls:'full',sticky:true,html:`<div class="stack">
   ${fsec('Visit',`<div class="grid g3"><label class="fld">Date<input type="date" data-c="ve-d" value="${VE.d}"></label><label class="fld">Time<input type="time" data-c="ve-tm" value="${VE.tm}"></label><label class="fld">Visit type<select data-i="ve" data-f="vtype">${VISIT_TYPES.map(x=>`<option${x===VE.vtype?' selected':''}>${x}</option>`).join('')}</select></label></div><div class="mut" id="ve-tod"></div>`)}
   ${fsec('Complaints',`${fld('Main complaint / problem','complaint',{area:3,ph:'What is the patient suffering from?'})}<div class="grid g2">${fld('Since when / how long','since',{ph:'e.g. 3 weeks'})}${fld('Result of last medicine (if follow-up)','progress',{ph:'e.g. cough less, sleep better'})}</div>${fld('Symptoms, what makes it better / worse','symptoms',{area:3})}<label class="fld">Overall result since last visit<select data-i="ve" data-f="outcome">${OUTCOMES.map(x=>`<option${x===VE.outcome?' selected':''}>${x}</option>`).join('')}</select></label>`)}
   <details class="help"${VE.bp||VE.pulse||VE.temp||VE.wt||VE.spo2||VE.exam?' open':''}><summary>Examination &amp; vitals (optional)</summary><div class="stack" style="margin-top:.7rem">${fld('Examination / observations','exam',{area:2})}<div class="grid g3">${fld('Blood pressure','bp',{ph:'120/80'})}${fld('Pulse','pulse',{num:1})}${fld('Temperature','temp',{ph:'98.6 F'})}</div><div class="grid g2">${fld('Weight','wt',{ph:'kg'})}${fld('SpO₂ %','spo2',{num:1})}</div></div></details>
   ${fld('Diagnosis (if any)','dx',{ph:'e.g. Acute bronchitis'})}
   <div id="veprev"></div>${fsec('Prescription – medicines given',`<div class="bar" style="margin:0 0 .5rem"><button class="btn sm" data-a="ve-pick">${ico('plus')} From my stock</button><button class="btn sm" data-a="ve-free">${ico('plus')} Type a medicine</button><button class="btn sm" data-a="ve-last">${ico('copy')} Copy last visit's medicines</button></div><div id="vel"></div><div id="vechg"></div>`)}
   ${fsec('Advice &amp; follow-up',`<div class="fld">Parhez (diet rules) – tap to select<div class="chips" id="vepar" style="flex-wrap:wrap;overflow:visible"></div></div>${fld('Other advice, diet, precautions','advice',{area:3})}<div class="grid g2"><label class="fld">Come back on<input type="date" data-c="ve-f" value="${esc(VE.follow)}"></label>${fld('Consultation fee','fee',{num:1})}</div><div class="chips" style="padding:0">${[[3,'3 days'],[7,'1 week'],[14,'2 weeks'],[30,'1 month'],[60,'2 months']].map(([n,t])=>`<button class="chip" data-a="ve-fq" data-n="${n}">+${t}</button>`).join('')}<button class="chip" data-a="ve-fq" data-n="0">Clear</button></div>${fld('Private notes (not printed)','notes',{area:3})}`)}</div>`,
   mount(){drawVE()},foot:[{t:'Cancel',fn:()=>{}},{t:'Save visit',fn:()=>{saveVE()}},{t:'Save & bill medicines',cls:'pri',fn:()=>{const r=saveVE();if(!r)return false;setTimeout(()=>A['visit-bill']({id:r.id}),50)}}]})}
function saveVE(){const[h,m]=(VE.tm||'00:00').split(':').map(Number);const dt=new Date(VE.d+'T00:00:00');dt.setHours(h||0,m||0,0,0);
  const o={...VE};delete o.tm;o.t=dt.getTime();o.rx=VE.rx.filter(r=>(r.nm||'').trim());o.rx.forEach(r=>{if(r.pot&&!potList().includes(r.pot))remember('xPot',r.pot)});
  const r=DB.put('visits',o);toast('Visit saved','ok');VE.id=r.id;return r}
function drawVE(){const el=$('#vel');if(!el)return;
  el.innerHTML=VE.rx.length?VE.rx.map((r,i)=>`<div class="rxl"><div class="rxh">${r.it?`<b>${esc(r.nm)}</b>`:`<input data-i="ve-r" data-idx="${i}" data-f="nm" value="${esc(r.nm)}" placeholder="Medicine name" dir="auto">`}<button class="ib" data-a="ve-rm" data-idx="${i}" aria-label="Remove">${ico('trash')}</button></div>
   <div class="grid g3"><label class="fld">Potency<input data-i="ve-r" data-idx="${i}" data-f="pot" value="${esc(r.pot||'')}" list="dl-pot2" placeholder="30C or your own" dir="auto"></label><label class="fld">Dose<input data-i="ve-r" data-idx="${i}" data-f="dose" value="${esc(r.dose||'')}" placeholder="4 pills / 5 drops" dir="auto"></label><label class="fld">How often<select data-c="ve-rf" data-idx="${i}"><option value="">—</option>${FREQS.map(x=>`<option${x===r.freq?' selected':''}>${x}</option>`).join('')}</select></label></div>
   <div class="grid g3"><label class="fld">For how many days<input data-i="ve-r" data-idx="${i}" data-f="days" value="${esc(r.days||'')}" inputmode="numeric" placeholder="7"></label><label class="fld">Quantity given<input data-i="ve-r" data-idx="${i}" data-f="qty" value="${esc(r.qty||'')}" inputmode="decimal" placeholder="1 bottle"></label><div class="fld"><span>Medicine ends on</span><b id="rxend${i}" style="padding:.6rem 0">${num(r.days)?fdate(addD(VE.d,num(r.days))):'—'}</b></div></div>
   <div class="grid g2"><label class="fld">Medium / vehicle<input data-i="ve-r" data-idx="${i}" data-f="medium" value="${esc(r.medium||'')}" list="dl-med" placeholder="e.g. Globules No. 30" dir="auto"></label><label class="fld">Directions (printed on label / Rx)<input data-i="ve-r" data-idx="${i}" data-f="dir" value="${esc(r.dir||'')}" placeholder="e.g. 4 pills 3 times a day" dir="auto"></label></div>
   <div class="chips" style="padding:0">${MEDIUMS.slice(0,4).map(x=>`<button class="chip" data-a="ve-med" data-idx="${i}" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div><div class="chips" style="padding:0">${DIRS.map(x=>`<button class="chip" data-a="ve-dir" data-idx="${i}" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div></div>`).join('')+`<datalist id="dl-med">${MEDIUMS.map(p=>`<option value="${esc(p)}">`).join('')}</datalist><datalist id="dl-pot2">${potList().map(p=>`<option value="${esc(p)}">`).join('')}</datalist>`:'<div class="mut">No medicines added yet.</div>';
  drawChg();drawPrev();drawPar();const t=$('#ve-tod');if(t){const[h]=(VE.tm||'0:0').split(':');t.textContent='Time of day: '+TOD(+h)[0]}}
let PREV=null;
function drawPrev(){const el=$('#veprev');if(!el)return;const vs=patVisits(VE.pat).filter(x=>x.id!==VE.id&&(VE.id?(x.t||0)<(VE.t||9e15):true));const l=vs[vs.length-1];PREV=l||null;
  if(!l){el.innerHTML='';return}
  const rx=(l.rx||[]).filter(r=>r.nm);
  el.innerHTML=`<div class="prevbox"><b>Last visit · ${fdate(l.d)}</b>${l.outcome?` <span class="badge ${/better/i.test(l.outcome)?'ok':l.outcome==='Worse'?'bad':'warn'}">${esc(l.outcome)}</span>`:''}<div class="mut" style="margin:.2rem 0 .4rem">${esc([l.complaint&&'Complaint: '+l.complaint,l.progress&&'Result: '+l.progress].filter(Boolean).join(' · '))||'—'}</div>
   ${rx.map((r,i)=>{const np=nextPot(r.pot);return`<div class="row static" style="margin:.25rem 0;background:var(--card)"><div class="r-main"><b>${esc(rxLabel(r))}</b><small>${esc([r.dose,r.freq,r.days&&r.days+' days'].filter(Boolean).join(' · '))}</small></div><div style="display:flex;gap:.3rem;flex-wrap:wrap"><button class="btn sm" data-a="ve-padd" data-i="${i}">Same</button>${np?`<button class="btn sm" data-a="ve-padd" data-i="${i}" data-np="${np}">↑ ${np}</button>`:''}</div></div>`}).join('')||'<div class="mut">No medicines were recorded.</div>'}
   <div class="mut" style="font-size:.85rem;margin-top:.3rem">“Same” repeats the previous potency, “↑” steps it up. You can edit everything below.</div></div>`}
function drawPar(){const el=$('#vepar');if(!el)return;VE.parhez=VE.parhez||[];const all=[...PARHEZ,...VE.parhez.filter(x=>!PARHEZ.includes(x))];el.innerHTML=all.map(x=>`<button class="chip ${VE.parhez.includes(x)?'on':''}" data-a="ve-par" data-v="${esc(x)}">${esc(x)}</button>`).join('')}
A['ve-par']=d=>{VE.parhez=VE.parhez||[];const i=VE.parhez.indexOf(d.v);if(i>=0)VE.parhez.splice(i,1);else VE.parhez.push(d.v);drawPar()};
A['ve-padd']=d=>{if(!PREV)return;const r=(PREV.rx||[]).filter(x=>x.nm)[+d.i];if(!r)return;const n={...r};delete n.stop;if(d.np)n.pot=d.np;VE.rx.push(n);drawVE();toast(d.np?'Added with higher potency '+d.np:'Added same medicine','ok')};
A['ve-med']=d=>{VE.rx[+d.idx].medium=d.v;drawVE()};
A['ve-dir']=d=>{VE.rx[+d.idx].dir=d.v;drawVE()};
function drawChg(){const ch=rxChange({...VE,t:VE.id?VE.t:0});if(!$('#vechg'))return;
  $('#vechg').innerHTML=ch?`<div class="inline-note" style="margin-top:.6rem"><b>Medicine changed since last visit:</b> ${ch.added.length?'added '+esc(ch.added.join(', ')):''}${ch.added.length&&ch.dropped.length?' · ':''}${ch.dropped.length?'stopped '+esc(ch.dropped.join(', ')):''}</div><label class="fld" style="margin-top:.5rem">Why was the medicine changed?<input data-i="ve" data-f="chgReason" value="${esc(VE.chgReason||'')}" dir="auto" placeholder="e.g. no improvement, new symptoms"></label>`:''}
HI.ve=(v,el,d)=>{VE[d.f]=v};
HI['ve-r']=(v,el,d)=>{const r=VE.rx[+d.idx];if(!r)return;r[d.f]=v;if(d.f==='nm'||d.f==='pot')drawChg();if(d.f==='days'){const e=$('#rxend'+d.idx);if(e)e.textContent=num(v)?fdate(addD(VE.d,num(v))):'—'}};
HC['ve-rf']=(v,el,d)=>{VE.rx[+d.idx].freq=v};
HC['ve-d']=v=>{VE.d=v;drawVE()};HC['ve-tm']=v=>{VE.tm=v;const t=$('#ve-tod');if(t)t.textContent='Time of day: '+TOD(+v.split(':')[0])[0]};HC['ve-f']=v=>{VE.follow=v};
A['ve-fq']=(d,b)=>{const i=b.closest('.fsec').querySelector('[data-c="ve-f"]');VE.follow=+d.n?addD(VE.d,+d.n):'';i.value=VE.follow};
A['ve-rm']=d=>{VE.rx.splice(+d.idx,1);drawVE()};
A['ve-free']=()=>{VE.rx.push({it:'',nm:'',pot:'',dose:'',freq:'Three times a day',days:'',qty:''});drawVE()};
A['ve-pick']=()=>pickItem(it=>{VE.rx.push({it:it.id,nm:it.name,pot:it.potency||'',dose:'',freq:'Three times a day',days:'',qty:''});drawVE()},{allowNew:true});
A['ve-last']=()=>{const vs=patVisits(VE.pat).filter(x=>x.id!==VE.id);const l=vs[vs.length-1];if(!l||!(l.rx||[]).length){toast('No earlier visit with medicines');return}
  (l.rx||[]).filter(r=>r.nm&&!r.stop).forEach(r=>{if(!VE.rx.some(x=>rxKey(x)===rxKey(r)))VE.rx.push({...r,stop:'',reason:''})});drawVE()};

/* ---------------- Parties: customers & suppliers ---------------- */
const PT={k:'c'},PQ={c:'',s:''};
const partiesView=(k,title)=>({title,render(){PT.k=k;const noun=k==='c'?'customer':'supplier';
  return`${k==='s'?'<p class="mut" style="margin:0 0 .7rem">Distributors you buy medicines from. Link each medicine to its supplier (in the medicine form) and the app builds the order list for you when stock runs low.</p>':''}<div class="bar"><div class="search">${ico('search')}<input data-i="pt-q" placeholder="Search…" value="${esc(PQ[k])}" dir="auto"></div><button class="btn pri" data-a="pt-new">${ico('plus')} Add ${noun}</button></div><div id="ptl"></div>`},mount(){PT.k=k;drawParties()}});
V.people=partiesView('c','Customers');V.suppliers=partiesView('s','Suppliers');
function drawParties(){const el=$('#ptl');if(!el)return;const q=PQ[PT.k].toLowerCase(),col=PT.k==='c'?'customers':'suppliers';
  const ps=DB.all(col).filter(p=>!q||(p.name+' '+(p.phone||'')+' '+(p.person||'')).toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name));
  el.innerHTML=ps.length?ps.map(p=>{const b=PT.k==='c'?custBal(p.id):supBal(p.id);const n=PT.k==='s'?DB.all('items').filter(i=>i.sup===p.id&&!i.arch).length:0,low=PT.k==='s'?DB.all('items').filter(i=>i.sup===p.id&&!i.arch&&['low','out','neg'].includes(istate(i))).length:0;
   return`<div class="row" data-a="pt-open" data-id="${p.id}"><span class="av">${esc((p.name||'?')[0].toUpperCase())}</span><div class="r-main"><b>${esc(p.name)}</b><small>${esc([p.person,p.phone].filter(Boolean).join(' · '))}${PT.k==='s'?' · '+n+' medicine(s)':''}</small></div><div class="r-side">${low?`<span class="badge warn">${low} to reorder</span>`:''}${b>0.5?`<span class="badge ${PT.k==='c'?'warn':'bad'}">${PT.k==='c'?'Owes':'We owe'} ${money(b)}</span>`:''}</div></div>`}).join(''):emptyBox(PT.k==='c'?'No customers yet':'No suppliers yet',PT.k==='s'?'Add the distributors you buy from.':'Add them here or while billing.')}
HI['pt-q']=v=>{PQ[PT.k]=v;drawParties()};
A['pt-new']=()=>partyForm(PT.k,null,()=>{});
A['pt-open']=d=>openParty(PT.k,d.id);
function partyForm(kind,id,cb){
  const col=kind==='c'?'customers':'suppliers',p=id?DB.get(col,id):{};
  modal({title:(id?'Edit ':'New ')+(kind==='c'?'customer':'supplier'),html:`<form class="stack" onsubmit="return false">${F.t(kind==='s'?'Supplier / company name *':'Name *','name',p.name,{required:true})}${kind==='s'?F.t('Contact person','person',p.person):F.s('Type','kind',['Customer','Doctor / practitioner','Wholesale buyer','Family / household'],p.kind||'Customer')}<div class="grid g2">${F.t('Phone (for WhatsApp)','phone',p.phone,{inputmode:'tel',placeholder:'03xx xxxxxxx'})}${kind==='s'?F.t('Email (to send order lists)','email',p.email,{type:'email'}):''}</div>${F.t('Address','addr',p.addr)}${F.a('Notes (remembrance)','note',p.note,{rows:3,placeholder:kind==='s'?'e.g. delivers Tuesdays, gives 5% on cash':'e.g. pays at month end'})}</form>`,
   foot:[{t:'Cancel',fn:()=>{}},{t:'Save',cls:'pri',fn:el=>{const f=formData(el);if(!f.name.trim()){toast('Name is required','bad');return false}const r=DB.put(col,{...p,name:f.name.trim(),person:(f.person||'').trim(),email:(f.email||'').trim(),phone:f.phone.trim(),addr:f.addr,note:f.note});toast('Saved','ok');cb&&cb(r.id)}}]})}
function openParty(kind,id){
  const col=kind==='c'?'customers':'suppliers',p=DB.get(col,id);if(!p)return;const bal=kind==='c'?custBal(id):supBal(id);
  const led=[];
  if(kind==='c'){DB.all('sales').filter(s=>s.cust===id&&!s.void).forEach(s=>led.push({d:s.d,t:s.t,l:'Bill '+s.no,debit:s.total,credit:s.paid}))}
  else DB.all('purchases').filter(s=>s.sup===id).forEach(s=>led.push({d:s.d,t:s.t,l:'Purchase '+s.no,debit:s.total,credit:s.paid}));
  DB.all('payments').filter(x=>x.k===kind&&x.pid===id).forEach(x=>led.push({d:x.d,t:x.t,l:'Payment'+(x.note?' – '+x.note:''),debit:0,credit:x.amt}));
  led.sort((a,b)=>a.t-b.t);let run=0;const rows=led.map(x=>{run=r2(run+x.debit-x.credit);return[fdate(x.d),x.l,x.debit||'',x.credit||'',run]});
  modal({title:esc(p.name),cls:'wide',sticky:false,html:`<div class="stack"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:.5rem"><div><small class="mut">${kind==='c'?'Customer owes':'We owe supplier'}</small><div class="qty" style="font-size:1.8rem;color:${bal>0.5?'var(--bad)':'var(--ok)'}">${money(Math.max(0,bal))}</div></div><div class="mut" style="text-align:right">${esc(p.phone||'')}<br>${esc(p.addr||'')}</div></div>${noteBox(p.note)}
   <div class="grid g2"><button class="btn pri" data-a="pay-new" data-k="${kind}" data-id="${id}">${ico('check')} ${kind==='c'?'Receive payment':'Pay supplier'}</button>
   ${kind==='c'?`<button class="btn" data-a="pay-remind" data-id="${id}">${ico('chat')} WhatsApp reminder</button>`:`<button class="btn" data-a="sup-order" data-id="${id}">${ico('truck')} Order list (low stock auto-added)</button>`}
   <button class="btn" data-a="pt-edit" data-k="${kind}" data-id="${id}">${ico('edit')} Edit</button><button class="btn" data-a="note-new" data-ref="${esc((kind==='c'?'Customer: ':'Supplier: ')+p.name)}">${ico('note')} Add note</button></div>
   ${kind==='s'?(()=>{const its=DB.all('items').filter(i=>i.sup===id&&!i.arch).sort(byName);return`<div class="sec"><h3>Medicines from this supplier (${its.length})</h3></div>${its.slice(0,30).map(i=>`<div class="row" data-a="item-open" data-id="${i.id}"><div class="r-main"><b>${esc(iname(i))}</b></div><div class="r-side"><span class="qty ${istate(i)==='ok'?'':istate(i)}">${fq(qty(i.id))}</span></div></div>`).join('')||'<div class="mut">None linked yet. Choose this supplier when adding a medicine.</div>'}`})():''}<div class="sec"><h3>Ledger</h3>${rows.length?`<button class="btn sm" data-a="ledger-x" data-k="${kind}" data-id="${id}">${ico('download')} Export</button>`:''}</div>${rows.length?`<div class="tw"><table class="t"><thead><tr><th>Date</th><th>Details</th><th class="n">Debit</th><th class="n">Credit</th><th class="n">Balance</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${esc(r[1])}</td><td class="n">${r[2]}</td><td class="n">${r[3]}</td><td class="n"><b>${r[4]}</b></td></tr>`).join('')}</tbody></table></div>`:'<div class="mut">No transactions yet.</div>'}</div>`})}
A['pt-edit']=d=>{A.closeTop();partyForm(d.k,d.id)};
A['sup-order']=d=>{A.closeTop();const o=newOrderSeed(d.id),g=suggestions().find(x=>x.sup===d.id);if(g)o.lines=g.items.map(i=>orderLine(i,`stock ${fq(qty(i.id))} / min ${fq(reo(i))}`));orderEditor(o)};
A['ledger-x']=d=>{const p=DB.get(d.k==='c'?'customers':'suppliers',d.id);const led=[];
  if(d.k==='c')DB.all('sales').filter(s=>s.cust===d.id&&!s.void).forEach(s=>led.push({d:s.d,t:s.t,l:'Bill '+s.no,a:s.total,b:s.paid}));else DB.all('purchases').filter(s=>s.sup===d.id).forEach(s=>led.push({d:s.d,t:s.t,l:'Purchase '+s.no,a:s.total,b:s.paid}));
  DB.all('payments').filter(x=>x.k===d.k&&x.pid===d.id).forEach(x=>led.push({d:x.d,t:x.t,l:'Payment',a:0,b:x.amt}));led.sort((a,b)=>a.t-b.t);let run=0;
  exportMenu({title:'Ledger - '+p.name,head:['Date','Details','Debit','Credit','Balance'],rows:led.map(x=>[x.d,x.l,x.a,x.b,run=r2(run+x.a-x.b)]),text:null})};
A['pay-remind']=d=>{const p=DB.get('customers',d.id);window.open(waUrl(p.phone,`Assalam o Alaikum ${p.name},\nYour pending balance at ${CFG().shop} is ${money(custBal(d.id))}. Please pay at your convenience.\nThank you.`),'_blank')};
A['pay-new']=d=>{const col=d.k==='c'?'customers':'suppliers',p=DB.get(col,d.id),bal=d.k==='c'?custBal(d.id):supBal(d.id);
  modal({title:(d.k==='c'?'Receive from ':'Pay to ')+esc(p.name),html:`<form class="stack" onsubmit="return false"><div class="mut">Outstanding: <b>${money(bal)}</b></div>${F.n('Amount *','amt',bal>0?r2(bal):'',{required:true})}<div class="grid g2">${F.s('Method','method',['cash','bank','UPI / wallet','card'],'cash')}${F.d('Date','d',ymd())}</div>${F.t('Note','note')}</form>`,
   foot:[{t:'Cancel',fn:()=>{}},{t:'Save payment',cls:'pri',fn:el=>{const f=formData(el);if(num(f.amt)<=0){toast('Enter amount','bad');return false}DB.put('payments',{k:d.k,pid:d.id,amt:num(f.amt),d:f.d||ymd(),t:Date.now(),method:f.method,note:f.note});toast('Payment recorded','ok');A.closeTop();openParty(d.k,d.id)}}]})};

/* ---------------- Reports ---------------- */
const RU={t:'sales',range:'30d',from:'',to:''};
const REPN={closing:'Daily closing',sales:'Sales',profit:'Profit & top sellers',purchases:'Purchases',valuation:'Stock value',expiry:'Expiry',reorder:'Reorder',moves:'Stock movements',dues:'Dues'};
function rangeOf(){const t=ymd();switch(RU.range){case'today':return[t,t];case'yday':return[addDays(-1),addDays(-1)];case'7d':return[addDays(-6),t];case'month':return[t.slice(0,8)+'01',t];case'custom':return[RU.from||t,RU.to||t];default:return[addDays(-29),t]}}
const inR=(d,[a,b])=>d>=a&&d<=b;
const REPS={
 closing(R){const ss=DB.all('sales').filter(s=>!s.void&&inR(s.d,R)),pays=DB.all('payments').filter(p=>inR(p.d,R)),man=DB.all('daysales').filter(x=>inR(x.d,R)),mm=m=>r2(man.filter(x=>(x.method||'cash')===m).reduce((a,x)=>a+num(x.amt),0));
  const by=m=>r2(ss.filter(s=>s.method===m).reduce((a,s)=>a+s.paid,0)),coll=(k,m)=>r2(pays.filter(p=>p.k===k&&(!m||p.method===m)).reduce((a,p)=>a+p.amt,0));
  const billed=r2(ss.reduce((a,s)=>a+s.total,0)+man.reduce((a,x)=>a+num(x.amt),0)),credit=r2(ss.reduce((a,s)=>a+s.total-s.paid,0)+mm('credit')),expo=r2(DB.all('expenses').filter(x=>inR(x.d,R)).reduce((a,x)=>a+num(x.amt),0)),cashIn=r2(by('cash')+mm('cash')+coll('c','cash')-coll('s','cash')-expo);
  const rows=[['Total sales (bills + day entries)',billed],['  Received in cash (bills)',by('cash')],['  Day-sale entries: cash',mm('cash')],['  Day-sale entries: online / card',mm('online')],['  Received by card',by('card')],['  Received by UPI / wallet',by('UPI / wallet')],['  Received by bank',by('bank')],['  Given on credit (not yet paid)',credit],['Collected from customers (old dues)',coll('c')],['Paid to suppliers',coll('s')],['Expenses paid from cash',expo],['CASH IN HAND from today’s activity',cashIn]];
  return{title:'Daily closing',head:['Item','Amount'],rows,kpis:[['Sales',money(billed)],['Cash in hand',money(cashIn)],['On credit',money(credit)],['Bills',ss.length]]}},
 sales(R){const ss0=DB.all('sales').filter(s=>!s.void&&inR(s.d,R)),man=DB.all('daysales').filter(x=>inR(x.d,R));const ss=[...ss0,...man.map(x=>({no:'Day entry',d:x.d,t:x.t,cust:'',lines:[],total:num(x.amt),paid:x.method==='credit'?0:num(x.amt),method:x.method||'cash',manual:1,mp:num(x.profit)}))].sort((a,b)=>a.t-b.t);
  const tot=ss.reduce((s,x)=>s+x.total,0),cost=ss0.reduce((s,x)=>s+x.lines.reduce((a,l)=>a+(l.cost||0),0),0)-man.reduce((s,x)=>s+num(x.profit),0)+man.reduce((s,x)=>s+num(x.amt),0)*0;
  const byDay=new Map();ss.forEach(s=>byDay.set(s.d,(byDay.get(s.d)||0)+s.total));
  const days=[];for(let d=R[0];d<=R[1]&&days.length<62;d=addDays(1,new Date(d+'T12:00:00')))days.push({l:fdate(d).slice(0,5),v:byDay.get(d)||0});
  return{title:'Sales report',head:['Bill','Date','Customer','Items','Total','Paid','Balance','Method'],rows:ss.map(s=>[s.no,s.d,s.manual?'(no bill)':custName(s.cust)||'Walk-in',s.lines.length,s.total,s.paid,r2(s.total-s.paid),s.method]),foot:['TOTAL','','',ss.reduce((a,s)=>a+s.lines.length,0),r2(tot),r2(ss.reduce((a,s)=>a+s.paid,0)),r2(ss.reduce((a,s)=>a+s.total-s.paid,0)),''],
   kpis:[['Sales',money(tot)],['Bills',ss.length],['Avg bill',money(ss.length?tot/ss.length:0)],['Gross profit',money(ss0.reduce((a,x)=>a+x.total,0)-ss0.reduce((a,x)=>a+x.lines.reduce((b,l)=>b+(l.cost||0),0),0)+man.reduce((a,x)=>a+num(x.profit),0))]],chart:days.length>1&&days.length<=31?days:null}},
 profit(R){const m=new Map();DB.all('sales').filter(s=>!s.void&&inR(s.d,R)).forEach(s=>s.lines.forEach(l=>{const k=l.mx?'Mixture: '+(l.mx.name||'custom'):l.nm;const x=m.get(k)||{q:0,rev:0,cost:0};x.q+=l.q;x.rev+=l.q*l.p;x.cost+=l.cost||0;m.set(k,x)}));
  const rows=[...m.entries()].map(([k,x])=>[k,r3(x.q),r2(x.rev),r2(x.cost),r2(x.rev-x.cost),x.rev?Math.round((x.rev-x.cost)/x.rev*100):0]).sort((a,b)=>b[4]-a[4]);
  const rev=rows.reduce((s,r)=>s+r[2],0),cost=rows.reduce((s,r)=>s+r[3],0);return{title:'Profit & top sellers',head:['Item','Qty sold','Revenue','Cost','Profit','Margin %'],rows,foot:['TOTAL','',r2(rev),r2(cost),r2(rev-cost),rev?Math.round((rev-cost)/rev*100):0],kpis:[['Revenue',money(rev)],['Cost',money(cost)],['Profit',money(rev-cost)]]}},
 purchases(R){const ps=DB.all('purchases').filter(p=>inR(p.d,R)).sort((a,b)=>a.t-b.t);return{title:'Purchases',head:['GRN','Date','Supplier','Invoice','Total','Paid','Due'],rows:ps.map(p=>[p.no,p.d,supName(p.sup),p.inv||'',p.total,p.paid,r2(p.total-p.paid)]),foot:['TOTAL','','','',r2(ps.reduce((s,p)=>s+p.total,0)),r2(ps.reduce((s,p)=>s+p.paid,0)),r2(ps.reduce((s,p)=>s+p.total-p.paid,0))],kpis:[['Purchased',money(ps.reduce((s,p)=>s+p.total,0))],['Invoices',ps.length]]}},
 valuation(){const rows=DB.all('items').filter(i=>!i.arch).sort(byName).map(i=>{const q=qty(i.id);return[iname(i),q,num(i.buy),r2(Math.max(0,q)*num(i.buy)),num(i.sell),r2(Math.max(0,q)*num(i.sell))]});const c=rows.reduce((s,r)=>s+r[3],0),rt=rows.reduce((s,r)=>s+r[5],0);
  return{title:'Stock valuation',head:['Medicine','Stock','Buy price','Cost value','Sell price','Retail value'],rows,foot:['TOTAL','','',r2(c),'',r2(rt)],kpis:[['Cost value',money(c)],['Retail value',money(rt)],['Potential profit',money(rt-c)]],noRange:true}},
 expiry(){const t=ymd(),rows=DB.all('batches').map(b=>({b,q:bq(b.id),it:DB.get('items',b.item)})).filter(x=>x.q>0&&x.b.exp&&x.it).sort((a,b)=>a.b.exp<b.b.exp?-1:1).map(x=>[iname(x.it),x.b.no||'',x.b.exp,Math.round((new Date(x.b.exp)-new Date(t))/864e5),x.q,r2(x.q*num(x.b.buy||x.it.buy)),expState(x.b)==='expired'?'EXPIRED':expState(x.b)==='soon'?'Expiring soon':'OK']);
  return{title:'Expiry report',head:['Medicine','Batch','Expiry','Days left','Qty','Cost value','Status'],rows,foot:['LOSS RISK (expired + soon)','','','','',r2(rows.filter(r=>r[6]!=='OK').reduce((s,r)=>s+r[5],0)),''],noRange:true,kpis:[['Expired',rows.filter(r=>r[6]==='EXPIRED').length],['Expiring soon',rows.filter(r=>r[6]==='Expiring soon').length]]}},
 reorder(){const rows=[];suggestions().forEach(g=>g.items.forEach(i=>rows.push([iname(i),qty(i.id),reo(i),suggestQty(i),supName(g.sup)||'—'])));return{title:'Reorder list',head:['Medicine','Stock','Reorder level','Suggested qty','Supplier'],rows,noRange:true,kpis:[['Items to reorder',rows.length]]}},
 moves(R){const rows=DB.all('moves').filter(m=>inR(m.d,R)).sort((a,b)=>b.t-a.t).slice(0,2000).map(m=>[m.d,iname(DB.get('items',m.item)),m.type,m.q,m.note||'']);return{title:'Stock movements',head:['Date','Medicine','Type','Qty','Note'],rows,kpis:[['Movements',rows.length]]}},
 dues(){const rows=[];DB.all('customers').forEach(c=>{const b=custBal(c.id);if(b>0.5)rows.push(['Customer owes us',c.name,c.phone||'',b])});DB.all('suppliers').forEach(c=>{const b=supBal(c.id);if(b>0.5)rows.push(['We owe supplier',c.name,c.phone||'',b])});
  return{title:'Dues (credit & payables)',head:['Type','Name','Phone','Amount'],rows,noRange:true,kpis:[['Receivable',money(rows.filter(r=>r[0][0]==='C').reduce((s,r)=>s+r[3],0))],['Payable',money(rows.filter(r=>r[0][0]==='W').reduce((s,r)=>s+r[3],0))]]}}};
V.reports={title:'Reports',live:false,render(){
  const R=rangeOf(),rep=REPS[RU.t](R);
  return`<div class="chips">${Object.entries(REPN).map(([k,t])=>`<button class="chip ${RU.t===k?'on':''}" data-a="rep-t" data-t="${k}">${t}</button>`).join('')}</div>
  ${rep.noRange?'':`<div class="bar"><select data-c="rep-r" style="width:auto">${[['today','Today'],['yday','Yesterday'],['7d','Last 7 days'],['30d','Last 30 days'],['month','This month'],['custom','Custom…']].map(([k,t])=>`<option value="${k}"${RU.range===k?' selected':''}>${t}</option>`).join('')}</select>${RU.range==='custom'?`<input type="date" data-c="rep-f" value="${R[0]}" style="width:auto"><input type="date" data-c="rep-to" value="${R[1]}" style="width:auto">`:`<span class="mut">${fdate(R[0])} – ${fdate(R[1])}</span>`}</div>`}
  <div class="grid kpis" style="grid-template-columns:repeat(auto-fit,minmax(9rem,1fr))">${rep.kpis.map(([l,v])=>`<div class="kpi" style="cursor:default"><small>${l}</small><b>${v}</b></div>`).join('')}</div>
  ${rep.chart?`<div class="card" style="margin-top:.8rem">${barChart(rep.chart)}</div>`:''}
  <div class="bar" style="margin-top:.8rem"><button class="btn pri" data-a="rep-x">${ico('download')} Export / Print</button><span class="mut">${rep.rows.length} rows</span></div>
  ${rep.rows.length?`<div class="tw"><table class="t"><thead><tr>${rep.head.map((h,i)=>`<th class="${typeof rep.rows[0][i]==='number'?'n':''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rep.rows.slice(0,400).map(r=>`<tr>${r.map((v,i)=>`<td class="${typeof v==='number'?'n':''}">${esc(typeof v==='number'&&!Number.isInteger(v)?v.toFixed(2):v)}</td>`).join('')}</tr>`).join('')}</tbody>${rep.foot?`<tfoot><tr>${rep.foot.map((v,i)=>`<td class="${typeof v==='number'?'n':''}">${esc(typeof v==='number'&&!Number.isInteger(v)?v.toFixed(2):v)}</td>`).join('')}</tr></tfoot>`:''}</table></div>${rep.rows.length>400?'<p class="mut">Showing 400 rows – export to see all.</p>':''}`:emptyBox('No data for this period')}`}};
A['rep-t']=d=>{RU.t=d.t;if(d.t==='closing')RU.range='today';render(true)};
HC['rep-r']=v=>{RU.range=v;render(true)};HC['rep-f']=v=>{RU.from=v;render(true)};HC['rep-to']=v=>{RU.to=v;render(true)};
A['rep-x']=()=>{const R=rangeOf(),rep=REPS[RU.t](R);exportMenu({title:rep.title,head:rep.head,rows:rep.rows,foot:rep.foot,sub:rep.noRange?'As of '+fdate(ymd()):fdate(R[0])+' to '+fdate(R[1]),fname:rep.title})};

/* ---------------- Alerts ---------------- */
function alertSec(title,cls,list,rowFn,extra=''){return list.length?`<div class="card"><h2><span>${title} <span class="badge ${cls}">${list.length}</span></span>${extra}</h2>${list.slice(0,40).map(rowFn).join('')}${list.length>40?`<div class="mut">+ ${list.length-40} more</div>`:''}</div>`:''}
V.alerts={title:'Alerts',render(){
  const a=alerts(),c=CFG();
  const itemRow=i=>`<div class="row" data-a="item-open" data-id="${i.id}"><div class="r-main"><b>${esc(iname(i))}</b><small>min ${fq(reo(i))}${supName(i.sup)?' · '+esc(supName(i.sup)):''}</small></div><div class="r-side"><span class="qty ${istate(i)}">${fq(qty(i.id))}</span></div><button class="btn sm" data-a="alert-order" data-id="${i.id}" title="Add to order list">${ico('truck')}</button></div>`;
  const bRow=cls=>x=>`<div class="row" data-a="item-open" data-id="${x.it.id}"><div class="r-main"><b>${esc(iname(x.it))}</b><small>Batch ${esc(x.b.no||'—')} · ${fdate(x.b.exp)} · ${Math.round((new Date(x.b.exp)-new Date(ymd()))/864e5)} days</small></div><div class="r-side"><span class="badge ${cls}">${fq(x.q)} left</span></div>${cls==='bad'?`<button class="btn sm bad" data-a="writeoff" data-b="${x.b.id}" title="Remove this expired batch from stock">Write off</button>`:''}</div>`;
  const all=alertSec('Out of stock','bad',a.out,itemRow,`<button class="btn sm" data-a="alert-order-all" data-k="out">Add all to order</button>`)+alertSec('Low stock','warn',a.low,itemRow,`<button class="btn sm" data-a="alert-order-all" data-k="low">Add all to order</button>`)+alertSec('Negative stock (check!)','bad',a.neg,itemRow)
   +alertSec('Expired – do not sell','bad',a.exps,bRow('bad'),`<button class="btn sm bad" data-a="writeoff-all">Write off all</button>`)+alertSec(`Expiring within ${c.expDays} days`,'warn',a.soon,bRow('warn'),`<button class="btn sm" data-a="ret-list">${ico('truck')} Return list</button>`)
   +alertSec('Customers with credit due','warn',a.dues,x=>`<div class="row" data-a="pt-open-c" data-id="${x.x.id}"><div class="r-main"><b>${esc(x.x.name)}</b><small>${esc(x.x.phone||'')}</small></div><div class="r-side"><b>${money(x.b)}</b></div></div>`)
   +(isOwner()?alertSec('Supplier payments due','warn',a.sdue,x=>`<div class="row" data-a="pt-open-s" data-id="${x.x.id}"><div class="r-main"><b>${esc(x.x.name)}</b></div><div class="r-side"><b>${money(x.b)}</b></div></div>`):'')
   +alertSec('Patient follow-ups','warn',a.follow,v=>{const p=DB.get('patients',v.pat)||{name:'?'};return`<div class="row" data-a="pat-open" data-id="${v.pat}"><div class="r-main"><b>${esc(p.name)}</b><small>${esc(v.complaint||'')}</small></div><span class="badge ${v.follow<ymd()?'bad':'warn'}">${fdate(v.follow)}</span>${p.phone?`<button class="btn sm" data-a="fu-wa" data-id="${v.id}">${ico('chat')} Remind</button>`:''}</div>`})
   +alertSec('Note reminders','warn',a.notes,n=>`<div class="row" data-a="note-open" data-id="${n.id}"><div class="r-main"><b>${esc(n.title||n.body.slice(0,40))}</b><small>${esc(n.body.slice(0,60))}</small></div><span class="badge warn">${fdate(n.due)}</span></div>`)
   +alertSec(`Slow / dead stock (no sale for ${c.deadDays}+ days)`,'mut',a.dead,i=>`<div class="row" data-a="item-open" data-id="${i.id}"><div class="r-main"><b>${esc(iname(i))}</b><small>last sold ${fdate(stock().last.get(i.id))||'never'}</small></div><div class="r-side"><span class="qty">${fq(qty(i.id))}</span></div></div>`)
   +alertSec('Overstock (6× reorder level)','mut',a.over,i=>`<div class="row" data-a="item-open" data-id="${i.id}"><div class="r-main"><b>${esc(iname(i))}</b></div><div class="r-side"><span class="qty">${fq(qty(i.id))}</span></div></div>`);
  return`<div class="bar"><span class="mut">Thresholds can be changed in Settings.</span></div>${all||`<div class="card">${emptyBox('All clear ✔','No stock, expiry, credit or follow-up problems right now.')}</div>`}`}};
A['alert-order']=d=>addToOrderDraft(d.id);
A.writeoff=async(d)=>{const b=DB.get('batches',d.b);if(!b)return;const it=DB.get('items',b.item);if(!await ask(`Remove ${fq(bq(b.id))} expired ${iname(it)} (batch ${b.no||'—'}) from stock?`,{ok:'Write off',bad:true}))return;writeOffBatch(b.id);toast('Written off','ok');render(true)};
A['writeoff-all']=async()=>{const l=alerts().exps;if(!await ask(`Remove ALL ${l.length} expired batches from stock? (Their value is lost.)`,{ok:'Write off all',bad:true}))return;let v=0;l.forEach(x=>{v+=x.q*num(x.it.buy);writeOffBatch(x.b.id)});toast(`${l.length} batches written off · loss ${money(v)}`,'ok');render(true)};
/* near-expiry return claim, grouped by supplier */
let RLD=90;
function retText(g){const c=CFG();return['*Near-expiry return request*',c.shop,fdate(ymd()),'',...g.rows.map(x=>`• ${iname(x.it)} – ${fq(x.q)} ${x.it.unit||''} · batch ${x.b.no||'—'} · exp ${fdate(x.b.exp)}`),'','Kindly arrange return / replacement before expiry. Thank you.'].join('\n')}
A['ret-list']=()=>{const gs=returnList(RLD);
  modal({title:'Near-expiry return list',cls:'wide',sticky:false,html:`<div class="stack"><p class="mut" style="margin:0">Medicines expiring soon, grouped by supplier. Send each distributor a claim <b>before</b> they expire – distributors refuse expired stock.</p>
   <div class="chips" style="padding:0">${[60,90,120].map(n=>`<button class="chip ${RLD===n?'on':''}" data-a="ret-days" data-n="${n}">Within ${n} days</button>`).join('')}</div>
   ${gs.length?gs.map(g=>`<div class="card" style="margin:0"><h2><span>${esc(supName(g.sup)||'No supplier set')}</span><span class="badge warn">${g.rows.length}</span></h2>${g.rows.map(x=>`<div class="mut" style="padding:.15rem 0">• <b style="color:var(--ink)">${esc(iname(x.it))}</b> – ${fq(x.q)} · batch ${esc(x.b.no||'—')} · exp ${fdate(x.b.exp)}</div>`).join('')}<div class="bar" style="margin:.6rem 0 0"><button class="btn sm pri" data-a="ret-wa" data-s="${g.sup}">${ico('chat')} WhatsApp</button><button class="btn sm" data-a="ret-pdf" data-s="${g.sup}">${ico('file')} PDF / Excel</button></div></div>`).join(''):emptyBox('Nothing near expiry','No stock expires in the next '+RLD+' days.')}</div>`})};
A['ret-days']=d=>{RLD=+d.n;A.closeTop();A['ret-list']()};
A['ret-wa']=d=>{const g=returnList(RLD).find(x=>x.sup===d.s);if(!g)return;const s=DB.get('suppliers',d.s);window.open(waUrl(s&&s.phone,retText(g)),'_blank')};
A['ret-pdf']=d=>{const g=returnList(RLD).find(x=>x.sup===d.s);if(!g)return;exportMenu({title:'Return list – '+(supName(d.s)||'Supplier'),sub:CFG().shop+' · '+fdate(ymd()),head:['Medicine','Qty','Batch','Expiry'],rows:g.rows.map(x=>[iname(x.it),x.q,x.b.no||'',x.b.exp]),text:retText(g),phone:(DB.get('suppliers',d.s)||{}).phone})};
A['alert-order-all']=d=>{const l=alerts()[d.k];l.forEach(i=>addToOrderDraft(i.id));toast(l.length+' items added to order lists','ok')};
A['pt-open-c']=d=>openParty('c',d.id);A['pt-open-s']=d=>openParty('s',d.id);
A.bell=()=>go('alerts');

/* ---------------- Settings ---------------- */
const UI=()=>ls.get('hs_ui',{theme:'auto',fs:17});
V.settings={title:'Settings',live:false,render(){
  const c=CFG(),ui=UI(),d=DEV();
  return`<div class="cols">
  <div><div class="card" data-form="shop"><h2>Shop &amp; clinic</h2><div class="stack">${F.t('Shop / clinic name','shop',c.shop)}<div class="grid g2">${F.t('Phone','phone',c.phone)}${F.t('Currency symbol','cur',c.cur)}</div><div class="grid g2">${F.t('Doctor name (printed on prescriptions)','doc',c.doc)}${F.t('Qualification','qual',c.qual,{placeholder:'e.g. DHMS, BHMS'})}</div>${F.t('Registration no.','reg',c.reg)}${F.t('Address','addr',c.addr)}<div class="grid g2">${F.s('Receipt size','receipt',[['a4','A4 / normal printer'],['thermal','80mm thermal printer']],c.receipt)}${F.t('Country dial code (WhatsApp)','cc',c.cc)}</div>${F.t('Receipt footer','footer',c.footer)}<button class="btn pri" data-a="set-save" data-f="shop">Save</button></div></div>
  <div class="card" data-form="pkgs"><h2>Treatment packages</h2><div class="stack"><div class="mut">One per line: <b>name | fee | days</b>. They appear as quick buttons on Sell and Today's sales. Days sets the patient's next follow-up (0 = none).</div><label class="fld"><textarea name="pkgs" rows="5" dir="auto">${esc(pkgList().map(p=>p.n+' | '+p.fee+' | '+p.days).join('\n'))}</textarea></label><button class="btn pri" data-a="set-save" data-f="pkgs">Save</button></div></div>
  <div class="card" data-form="alerts"><h2>Alerts &amp; rules</h2><div class="stack"><div class="grid g2">${F.n('Warn before expiry (days)','expDays',c.expDays)}${F.n('Default low-stock level','defReorder',c.defReorder)}</div>${F.n('Slow stock: days without a sale','deadDays',c.deadDays)}${F.c('Allow selling more than the stock (negative stock)','allowNeg',c.allowNeg)}<button class="btn pri" data-a="set-save" data-f="alerts">Save</button></div></div></div>
  <div><div class="card" data-form="dev"><h2>This device</h2><div class="stack"><div class="grid g2">${F.t('Device name','dname',d.name,{placeholder:'e.g. Dr. phone'})}${F.s('Theme','theme',[['auto','Automatic'],['light','Light'],['dark','Dark']],ui.theme)}</div>${F.s('Text size','fs',[['16','Normal'],['18','Large'],['20','Extra large']],String(ui.fs>=20?20:ui.fs>=18?18:16))}<div class="mut">Device code <b>${esc(d.code)}</b> is used in bill numbers.</div><button class="btn pri" data-a="set-save" data-f="dev">Save</button></div></div>
  <div class="card"><h2>Security &amp; staff access</h2><div class="stack"><p class="mut" style="margin:0">Set an <b>Owner PIN</b> for yourself and a <b>Staff PIN</b> for helpers. Staff can bill and manage stock but cannot see purchase prices, profit, reports, backups or settings. The app locks itself after 5 minutes without use.</p><div class="grid g2"><button class="btn" data-a="set-pin" data-k="o">${ico('lock')} ${ls.get('hs_pin',null)?'Change Owner PIN':'Set Owner PIN'}</button><button class="btn" data-a="set-pin" data-k="s">${ico('lock')} ${ls.get('hs_pin2',null)?'Change Staff PIN':'Set Staff PIN'}</button></div></div></div>
  <div class="card"><h2>Data</h2><div class="stack"><a class="btn pri" href="#/backup">${ico('up')} Backup &amp; restore</a><button class="btn" data-a="import-csv">${ico('download')} Import medicines from Excel / CSV</button><button class="btn" data-a="stock-export">${ico('file')} Export stock list</button><button class="btn" data-a="demo">Load demo data</button><button class="btn bad" data-a="wipe">Erase all data on this phone</button></div></div></div></div>`}};
A['set-save']=(d,btn)=>{const card=btn.closest('[data-form]'),f=formData(card);
  if(d.f==='shop')DB.put('settings',{...(DB.get('settings','main')||{}),id:'main',shop:f.shop.trim()||DEFCFG.shop,phone:f.phone,cur:f.cur||'Rs',addr:f.addr,receipt:f.receipt,cc:f.cc||'92',footer:f.footer,doc:f.doc,qual:f.qual,reg:f.reg});
  if(d.f==='alerts')DB.put('settings',{...(DB.get('settings','main')||{}),id:'main',expDays:num(f.expDays)||90,defReorder:num(f.defReorder)||3,deadDays:num(f.deadDays)||90,allowNeg:!!f.allowNeg});
  if(d.f==='pkgs'){const l=(f.pkgs||'').split('\n').map(x=>x.split('|').map(y=>y.trim())).filter(a=>a[0]).map(a=>({n:a[0],fee:num(a[1]),days:Math.max(0,Math.floor(num(a[2])))}));DB.put('settings',{...(DB.get('settings','main')||{}),id:'main',pkgs:l})}
  if(d.f==='dev'){const dv=DEV();ls.set('hs_dev',{...dv,name:f.dname.trim()});ls.set('hs_ui',{theme:f.theme,fs:+f.fs});applyTheme()}
  toast('Saved','ok');chrome()};
A.wipe=async()=>{if(!await ask('Erase ALL data stored on this phone?\n\nThis cannot be undone. Make a backup first (More → Backup).',{ok:'Erase',bad:true}))return;if(!await ask('Are you really sure? All medicines, patients and sales will be deleted.',{ok:'Yes, erase everything',bad:true}))return;await DB.wipe();CART=newCart();saveCart();toast('Phone data erased','ok')};
A['set-pin']=d=>{const staff=d.k==='s',key=staff?'hs_pin2':'hs_pin',has=!!ls.get(key,null);
  modal({title:staff?'Staff PIN':'Owner PIN',html:`<form class="stack" onsubmit="return false"><p class="mut" style="margin:0">${staff?'Helpers use this PIN. They get a limited view (no cost prices, profit, reports or settings).':'Only you know this PIN. It opens everything. The app asks for it when opened and after 5 minutes of no use.'}</p>${F.t('New PIN (4–6 digits)','pin','',{inputmode:'numeric',maxlength:6,type:'password'})}</form>`,
   foot:[...(has?[{t:'Remove PIN',cls:'bad',fn:()=>{if(!staff&&ls.get('hs_pin2',null)){toast('Remove the Staff PIN first','bad');return false}ls.set(key,null);toast('PIN removed','ok')}}]:[]),{t:'Cancel',fn:()=>{}},{t:'Save PIN',cls:'pri',fn:async el=>{const p=formData(el).pin;if(!/^\d{4,6}$/.test(p)){toast('Use 4 to 6 digits','bad');return false}
     if(staff&&!ls.get('hs_pin',null)){toast('Set the Owner PIN first','bad');return false}const h=await hashPin(p);if(staff&&h===ls.get('hs_pin',null)){toast('Staff PIN must differ from Owner PIN','bad');return false}ls.set(key,h);toast('PIN saved','ok')}}]})};
async function hashPin(p){try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('hs:'+p));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch(e){let h=5381;for(const c of 'hs:'+p)h=(h*33)^c.charCodeAt(0);return'x'+(h>>>0)}}
